function queryWenTiList(n){var i=$("#title").val(),t=parseInt(returnPage(n),10);$.ajax({async:!0,url:"/AppService/article/queryWenTiList.xhtml",data:{title:encodeURI(i),page:t},dataType:"json",cache:!1,type:"post",error:function(){},success:function(n){var u="",r="",f=n.list,e=n.currentPage,o=n.count,i=n.maxPages;if($("#page").val(e),$("#maxPages").val(i),f!=null&&f.length>0)$.each(f,function(n,t){u+="<dl>";u+="<dt>"+t.wWenti+"<\/dt>";u+="<i class='arrow'><\/i>";u+="<dd>"+t.wDaan+"<\/dd>";u+="<\/dl>"});else{$("#faqList").html("<span class='bulletin nomsg_tips'>暂无消息，敬请期待...<\/span>");$(".page").html("");return}$("#faqList").html(u);r+="<a href='javascript:queryWenTiList(\""+(t-1)+"\")' class='pre'><\/a>";r+=t==1?"<a class='act' href='javascript:queryWenTiList(\"1\")'>1<\/a>":"<a href='javascript:queryWenTiList(\"1\")'>1<\/a>";t>3&&(r+="<a class='omit'><\/a>");t-1>1&&(r+="<a href='javascript:queryWenTiList(\""+(t-1)+"\")'>"+(t-1)+"<\/a>");t!=1&&t!=i&&(r+="<a class='act' href='javascript:queryWenTiList(\""+t+"\")'>"+t+"<\/a>");t+1<i&&(r+="<a href='javascript:queryWenTiList(\""+(t+1)+"\")'>"+(t+1)+"<\/a>");i-t>2&&(r+="<a class='omit'><\/a>");t!=1?i==t?r+="<a class='act' href='javascript:queryWenTiList(\""+i+"\")'>"+i+"<\/a>":i>t&&(r+="<a href='javascript:queryWenTiList(\""+i+"\")'>"+i+"<\/a>"):i==t||i>t&&(r+="<a href='javascript:queryWenTiList(\""+i+"\")'>"+i+"<\/a>");r+="<a href='javascript:queryWenTiList(\""+(t+1)+"\")' class='next'><\/a>";$(".page").html(r);$(".FAQ dl dt,.FAQ dl i.arrow").click(function(){$(this).parent("dl").toggleClass("act").siblings().removeClass("act")})}})}function returnPage(n){var t=$("#maxPages").val();return parseInt(n,10)>=parseInt(t,10)?t:parseInt(n,10)<=0?"1":n}$(document).ready(function(){getUserRequest("pc_faq");$(".nav.fr ul li a").removeClass("current");queryWenTiList("1");document.title="常见问题_招商财富 都市精英的私人银行、高净值人士专业资产管理平台"})